begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select has_function('public','send_conversation_message',array['uuid','uuid','text'],'Guarded send exists');
insert into auth.users(id,email) select ('20500000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'message-'||n||'@example.invalid' from generate_series(1,5) n;
insert into public.memberships(user_id,role) select ('20500000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case when n=3 then 'admin' else 'member' end::public.member_role from generate_series(1,4) n;
insert into public.profiles(user_id,display_name,home_airport,pilot_designation) values('20500000-0000-4000-8000-000000000002','Message pilot','KPAO','licensed');
insert into public.flights(id,owner_id,departure_airport,destination_airport,departure_at,departure_timezone,aircraft_description,pilot_places,visibility)
select ('20510000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'20500000-0000-4000-8000-000000000001','KPAO','KSQL',now()+interval '2 days','UTC','Message C172',1,case when n=2 then 'PRIVATE' else 'NETWORK' end::public.flight_visibility from generate_series(1,3) n;
insert into public.flight_recipients(flight_id,user_id) values('20510000-0000-4000-8000-000000000002','20500000-0000-4000-8000-000000000002');
insert into public.flight_requests(id,flight_id,requester_id) select ('20520000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('20510000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'20500000-0000-4000-8000-000000000002' from generate_series(1,3) n;
update public.flight_requests set status='accepted' where id::text like '20520000%';
insert into public.conversations(id,flight_request_id,owner_id,requester_id) select ('20530000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('20520000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'20500000-0000-4000-8000-000000000001','20500000-0000-4000-8000-000000000002' from generate_series(1,3) n;
create function pg_temp.actor(n integer) returns text language sql as $$select set_config('request.jwt.claims',json_build_object('sub',('20500000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'role','authenticated','user_metadata',json_build_object('role','admin'))::text,true);$$;
create function pg_temp.send(thread integer default 1,body text default 'Hello',message uuid default gen_random_uuid()) returns jsonb language sql as $$select public.send_conversation_message(('20530000-0000-4000-8000-'||lpad(thread::text,12,'0'))::uuid,message,body);$$;
select ok(not has_function_privilege('anon','public.send_conversation_message(uuid,uuid,text)','EXECUTE'),'Anonymous RPC denied');
select ok(not has_function_privilege('service_role','public.send_conversation_message(uuid,uuid,text)','EXECUTE'),'Service-role RPC bypass denied');
select ok(not has_table_privilege('authenticated','public.messages','INSERT,UPDATE,DELETE'),'Direct table mutations stay closed');
select ok((select pubinsert and not pubupdate and not pubdelete and not pubtruncate and not puballtables from pg_publication where pubname='supabase_realtime'),'Only message INSERT events can be published');
select is((select array_agg(schemaname||'.'||tablename order by schemaname,tablename) from pg_publication_tables where pubname='supabase_realtime'),array['public.messages']::text[],'Publication includes only protected messages');
set local role authenticated;
select set_config('request.jwt.claims','{}',true);
select throws_ok($$select pg_temp.send()$$,'42501',null,'Missing identity denied');
select pg_temp.actor(3);
select throws_ok($$select pg_temp.send()$$,'42501',null,'Unrelated admin cannot send');
select pg_temp.actor(5);
select throws_ok($$select pg_temp.send()$$,'42501',null,'Identity without membership cannot send');
select pg_temp.actor(1);
select lives_ok($$select pg_temp.send(message=>'20640000-0000-4000-8000-000000000001')$$,'Owner can send on active connection');
select is(pg_temp.send(message=>'20640000-0000-4000-8000-000000000001')->>'senderId','20500000-0000-4000-8000-000000000001','Sender is derived from actual session');
select is((select count(*)::integer from public.messages where conversation_id='20530000-0000-4000-8000-000000000001'),1,'Exact retry stores only one message');
select throws_ok($$select pg_temp.send(body=>'Changed',message=>'20640000-0000-4000-8000-000000000001')$$,'22023',null,'Retry cannot replace body');
select throws_ok($$select pg_temp.send(thread=>2,message=>'20640000-0000-4000-8000-000000000001')$$,'22023',null,'Existing identity cannot be moved to another thread');
select throws_ok($$select pg_temp.send(body=>'')$$,'22023',null,'Empty input rejected without row detail');
select throws_ok($$select pg_temp.send(body=>E' \t\n')$$,'22023',null,'Whitespace-only input rejected');
select throws_ok($$select pg_temp.send(body=>repeat('x',4001))$$,'22023',null,'Oversized input rejected');
select throws_ok($$select public.send_conversation_message(null,gen_random_uuid(),'Hello')$$,'22023',null,'Missing conversation rejected');
select throws_ok($$select public.send_conversation_message('20530000-0000-4000-8000-000000000001',null,'Hello')$$,'22023',null,'Missing retry identity rejected');
select throws_ok($$select pg_temp.send(thread=>99)$$,'42501',null,'Unknown thread denied');
select pg_temp.actor(2);
select lives_ok($$select pg_temp.send(body=>repeat('😀',4000))$$,'Requester can send bounded Unicode');
select throws_ok($$select pg_temp.send(message=>'20640000-0000-4000-8000-000000000001')$$,'22023',null,'Counterpart cannot reuse another sender message identity');
reset role;
update public.memberships set status='disabled',disabled_at=now(),disabled_reason='Fixture' where user_id='20500000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select pg_temp.send()$$,'42501',null,'Disabled sender cannot send');
select pg_temp.actor(1);
select throws_ok($$select pg_temp.send()$$,'42501',null,'Disabled counterpart cannot support sending');
select is((select count(*)::integer from public.messages where conversation_id='20530000-0000-4000-8000-000000000001'),2,'Active counterpart still reads retained history');
reset role;
update public.memberships set status='active',disabled_at=null,disabled_reason=null where user_id='20500000-0000-4000-8000-000000000002';
set local role authenticated;
select pg_temp.actor(2);
select public.withdraw_flight_request('20510000-0000-4000-8000-000000000001','20520000-0000-4000-8000-000000000001');
select throws_ok($$select pg_temp.send()$$,'42501',null,'Withdrawal rejects new sends');
select throws_ok($$select pg_temp.send(message=>'20640000-0000-4000-8000-000000000001')$$,'42501',null,'Closed state is checked even before retry confirmation');
select public.submit_flight_interest('20510000-0000-4000-8000-000000000001');
select throws_ok($$select pg_temp.send()$$,'42501',null,'Pending resubmission cannot send');
select pg_temp.actor(1);
select public.decide_flight_request('20510000-0000-4000-8000-000000000001','20520000-0000-4000-8000-000000000001','accepted');
select throws_ok($$select pg_temp.send()$$,'42501',null,'Fresh acceptance still needs explicit thread open');
select public.get_or_create_flight_conversation('20520000-0000-4000-8000-000000000001');
select lives_ok($$select pg_temp.send()$$,'Reopened approved thread can send');
select public.change_flight_recipient('20510000-0000-4000-8000-000000000002','20500000-0000-4000-8000-000000000002',false);
select throws_ok($$select pg_temp.send(thread=>2)$$,'42501',null,'PRIVATE removal rejects sends');
select public.cancel_flight('20510000-0000-4000-8000-000000000003');
select throws_ok($$select pg_temp.send(thread=>3)$$,'42501',null,'Flight cancellation rejects sends');
select is((select count(*)::integer from public.messages where conversation_id='20530000-0000-4000-8000-000000000001'),3,'Denied sends never alter retained history');
reset role;
select * from finish();
rollback;
